contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract: make a deposit from this contract and then try withdrawAll as caller
    function runTest(uint depositAmount) public payable {
        // Preconditions: caller must send enough ETH to cover depositAmount to this test contract
        require(address(this).balance >= depositAmount, "insufficient balance for test");
        // make a deposit into C by sending funds to fallback
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // record balance of c after deposit
        uint balAfterDeposit = address(c).balance;

        // Now attempt to call withdrawAll as this non-owner caller
        // This is the key distinguishing call: in P it will revert due to onlyOwner, in M it will succeed
        bool ok;
        (ok,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Assert: if withdrawAll did not succeed (ok == false) then contract balance must remain equal to balAfterDeposit
        // This captures that non-owners cannot withdraw in the original contract
        // If withdrawAll succeeded (ok == true) then this assertion may fail under mutant M — making it distinguishing
        assert(address(c).balance == balAfterDeposit || ok == true);
    }

    // allow receiving ETH so the test harness can fund this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        // We must call withdrawAll from the provided caller. To simulate calls from a different caller
        // in this environment, we rely on the external caller of run to be the provided `caller` via tx.origin
        // but since we cannot change msg.sender, we instead require that the caller passed is not the stored owner
        // as observable via C.owner() getter. Ensure caller is not owner so original contract reverts.
        require(c.owner() != caller);
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // In the original contract, a non-owner call to withdrawAll must revert.
        assert(reverted == true);
    }
    receive() external payable { }
}

