pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: amount to send (value) and caller address that will invoke sendMoney
    function testFuzz_property(uint256 value, address caller) public {
        // keep value in a reasonable range so vm.deal won't overflow and caller is non-zero
        value = bound(value, 0, 1 ether);
        vm.assume(caller != address(0));

        // Deploy a helper that will accept funds but then revert on fallback to simulate adversarial external behavior
        Reverter reverter = new Reverter();

        // Fund contract C so it has balance to be attempted to send
        vm.deal(address(c), 1 ether);

        // Record withdrawAll() observable before the call: it's the contract's balance as withdrawAll forwards to withdraw
        uint256 before = address(c).balance;

        // Have the fuzzed caller invoke sendMoney targeting the reverter with value
        vm.deal(caller, value);
        vm.prank(caller);
        // craft empty data
        bytes memory data = "";
        // call sendMoney forwarding value
        // we wrap in try/catch to ensure test runs regardless of revert; the sendMoney itself should handle callee revert
        try c.sendMoney(address(reverter), value, data) {
            // call returned
        } catch {
            // ignore
        }

        uint256 after = address(c).balance;

        // General rule (single assertion): in the correct contract, calling sendMoney to an external adversarial callee must NOT reduce contract balance (owner-only withdraw prevents outsiders from draining balance). The mutant that removes onlyOwner allows outsiders to withdraw and thereby can change the balance for some inputs; thus the reference must always have before == after.
        assertTrue(before == after);
    }
}

// Adversarial helper: rejects any incoming call (reverts) to simulate external failure behavior
contract Reverter {
    fallback() external payable {
        revert();
    }
    receive() external payable {
        revert();
    }
}

