pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attackerAddr, uint256 sendAmount) public {
        // keep sendAmount within reasonable bounds and non-zero to have effect
        sendAmount = bound(sendAmount, 1, 1 ether);
        // deploy adversarial helper that will attempt to drain funds when called
        Attacker attacker = new Attacker(address(c));

        // fund contract c and the attacker EOA
        vm.deal(address(this), 2 ether);
        payable(address(c)).transfer(0); // noop to silence warnings
        // fund c so there is something to withdraw
        vm.deal(address(c), 0); // ensure predictable state
        // send ETH into c by calling its fallback via low-level call to increment depositsCount
        (bool suc, ) = address(c).call{value: 1 ether}("");
        require(suc);

        // record withdrawAll-equivalent observable: address(c).balance before
        uint256 beforeBal = address(c).balance;

        // have attacker contract receive a call from c: route sendMoney to attacker
        // attacker will in its fallback call c.withdrawAll() (attempt to exploit mutant)
        // fund attacker so it can be the msg.sender if needed
        vm.deal(address(attacker), 0);

        // call sendMoney to the attacker with some value (could be zero); use this contract as caller
        // pass attacker address (not fuzzed actorAddr) as the target to ensure adversarial behavior
        // sendAmount is fuzzed and can influence whether the attacker can drain
        bool ok;
        try c.sendMoney(address(attacker), sendAmount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // After sendMoney completes, the correct contract (with onlyOwner) ensures that
        // only the owner can withdraw funds; thus address(c).balance must remain >= 0 and
        // specifically cannot be drained by the external attacker call — i.e., in the REF
        // the balance must be unchanged except for the explicit sendMoney value transferred out.
        // We assert a universal property: the contract's balance cannot be reduced below the
        // withdrawAll-observable threshold caused by an external callee-triggered withdraw.
        // Here we assert that address(c).balance is >= 0 and, more usefully, that if sendMoney
        // completed (ok==true), then address(c).balance >= 0 still holds — this is trivially true,
        // but to target the mutant we assert that the balance after is >= before - sendAmount.

        uint256 afterBal = address(c).balance;
        // single assertion observing c: reference preserves that it cannot be drained beyond the sent value
        assertTrue(afterBal + sendAmount >= beforeBal);
    }
}

// Adversarial helper: when receiving a call from c, attempts to call back into c.withdrawAll()
contract Attacker {
    address public target;
    constructor(address _t) payable {
        target = _t;
    }
    fallback() external payable {
        // try to drain by calling withdrawAll on target; this should fail on the reference (onlyOwner)
        // but succeed on the mutant (no onlyOwner) allowing the attacker to reduce target's balance
        // we ignore success/failure
        (bool s, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        s;
    }
}

