import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: For any caller and any target that may revert when called, a non-owner calling sendMoney
    // cannot reduce the contract's balance on the REFERENCE contract C. The mutant that removes onlyOwner
    // allows a non-owner to perform actions (via external calls) that change address(c).balance for some inputs.
    // We fuzz the attacker address and the value sent to exercise the difference.
    function testFuzz_property(address attacker, uint256 value) public {
        // Keep domain wide but meaningful: attacker should not be the owner (owner is address(this) who deployed c)
        // and value should be a reasonable bounded amount so vm.deal can fund attacker. Do not overconstrain.
        vm.assume(attacker != address(0));
        // ensure attacker is not the contract deployer/owner
        vm.assume(attacker != address(this));
        // bound value to a practical range (0..1 ether)
        value = bound(value, 0, 1 ether);

        // Deploy a malicious helper that will accept funds and then call back into c.withdrawAll() if allowed
        // This helper models an adversarial external party whose behavior could lead to different observable state
        // between correct and mutant contracts when onlyOwner is removed.
        AttackerHelper helper = new AttackerHelper(c);

        // Fund the contract c with some Ether so there is a balance to potentially withdraw
        vm.deal(address(this), 1 ether);
        // send initial funds into c from the test runner (owner)
        c.sendMoney{value: 0.5 ether}(address(c), 0, ""); // no-op call to self but ensures c has some balance
        // Alternatively, directly send funds to c via low-level
        (bool s, ) = address(c).call{value: 0.5 ether}("");
        require(s);

        // Fund the attacker so it can send value when calling c.sendMoney
        vm.deal(attacker, value);

        // Now have the attacker call c.sendMoney targeting the helper; the helper's fallback will try to exploit
        vm.prank(attacker);
        // call sendMoney with the helper address and value; forward value from attacker
        // Wrap in try/catch to capture success but we will only assert on c's balance getter
        try c.sendMoney{value: value}(address(helper), value, "") {
            // ignore
        } catch {
            // ignore
        }

        // Single assertion: On the correct contract, only the owner can decrease the contract balance via withdrawAll/withdraw.
        // Therefore after the adversarial sendMoney call by a non-owner attacker, the contract's balance must remain >= 0.5 ether
        // (i.e., attacker should not be able to withdraw owner's funds). We read address(c).balance which the reference preserves
        // for all inputs; the mutant that removes onlyOwner may allow the attacker helper to call withdrawAll and reduce balance
        // for some fuzzed inputs, causing this assertion to fail.
        assertTrue(address(c).balance >= 0.5 ether);
    }
}

// Minimal adversarial helper: tries to call c.withdrawAll() when it receives funds.
