pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attackerValue (amount to send via sendMoney) and callDataChoice (0/1)
    // We fuzz an amount and a small uint that selects calldata; the adversarial helper embodies a reverter
    // that will attempt to call back into C.withdrawAll if it is allowed (exploiting removed onlyOwner).
    function testFuzz_property(uint256 attackerValue, uint8 callDataChoice) public {
        // keep amount within reasonable bounds and non-zero to exercise behavior
        uint256 value = bound(attackerValue, 0, 1 ether);

        // deploy an adversarial helper that attempts to trigger withdrawAll on callback if funded
        Attacker attacker = new Attacker(address(c));

        // fund C with some ETH so withdrawAll would have a balance to withdraw
        vm.deal(address(this), 1 ether);
        // send initial funds into contract C as owner (setUp deployer is owner)
        payable(address(c)).transfer(0.5 ether);

        // record balance before calling sendMoney
        uint256 before = address(c).balance;

        // choose calldata: 0 -> empty, 1 -> attacker-triggering payload (attacker expects any calldata)
        bytes memory data = callDataChoice % 2 == 0 ? bytes("") : abi.encodeWithSignature("poke()");

        // make owner call c.sendMoney targeting attacker; if onlyOwner restriction is present, attacker cannot call withdrawAll
        // but attacker will attempt in its fallback to call c.withdrawAll() (we fund attacker so it can forward gas)
        // vm.prank ensures msg.sender is the owner (deployer) when calling sendMoney
        vm.prank(address(this));
        // send some ETH along with the low-level call from C to attacker by instructing sendMoney to forward `value`
        // need to give C some ETH to forward: c already has balance from earlier transfer
        try c.sendMoney(address(attacker), value, data) {
            // call succeeded
        } catch {
            // ignore revert; some combinations may revert but the property concerns final balance
        }

        // After sendMoney returns, on the correct contract onlyOwner prevents attacker from calling withdrawAll inside its fallback,
        // so address(c).balance should be >= before - value (it might reduce by the forwarded value) but critically the owner-only withdraw can't be invoked by attacker to further drain funds.
        // The observable invariant we assert: the contract's balance never decreases below (before - value).
        // If the onlyOwner modifier was removed, attacker in fallback could call withdrawAll to drain more than value, making balance < before - value for some inputs.

        uint256 after = address(c).balance;

        // Single assertion reading c's public surface: compare balances as general property
        assertTrue(after >= before - value);
    }
}

// Adversarial helper: when called (via low-level call), it will try to call back into C.withdrawAll(), attempting to drain C if onlyOwner is removed.
contract Attacker {
    address payable public targetC;
    constructor(address _c) payable {
        targetC = payable(_c);
    }
    // arbitrary function to match encoded calldata; does nothing
    function poke() external {}
    // fallback will be invoked when C calls this contract; attempt to call withdrawAll on C
    fallback() external payable {
        // try to call withdrawAll on C; if onlyOwner removed, this will succeed and drain funds
        // use low-level call to avoid revert bubbling
        (bool s,) = targetC.call(abi.encodeWithSignature("withdrawAll()"));
        s; // ignore return
    }
}

